use serde_json::{Value,json};use std::panic::{catch_unwind,AssertUnwindSafe};
fn call<T:serde::Serialize>(f:impl FnOnce()->T)->Value{match catch_unwind(AssertUnwindSafe(f)){Ok(v)=>json!({"result":"ok","value":v}),Err(e)=>{let s=e.downcast_ref::<String>().map(String::as_str).or_else(||e.downcast_ref::<&str>().copied()).unwrap_or("");json!({"result":s.split(':').next().unwrap()})}}}
pub(crate) fn row(r:&KmoRowInfo)->Value{let d=r.atom.borrow().rawData();json!({"index":r.getRowIndex(),"rawRow":d.rowIndex,"height":r.getHeight(),"xf":r.getXFIndex(),"rawXF":r.getRawXFIndex(),"rawFlags":d.option_flag,"max":r.getMaxHeightCell(),"min":r.getMinHeightCell(),"hidden":r.isHidden(),"unsynced":r.isUnsynced(),"formatted":r.isFormated(),"hash":r.hashCode(),"hasSheet":r.kmoSheet.borrow().is_some(),"self":r.equals(Some(r)),"null":r.equals(None),"other":r.equals(Some(&"other"))})}
fn pairs(mut it:KmoRowRangeIterator)->Value{let mut out=vec![];while it.hasNext(){let p=it.next();out.push(json!([p.first,p.second]));}json!(out)}
pub(crate) fn clear(s:&KmoSheet){let range=s.getHiddenRowsManager().getRowRange();let mut it=range.iterator();let mut all=vec![];while it.hasNext(){let p=it.next();for n in p.first..=p.second{all.push(n);}}for n in all{range.removeRow(n);}s.getHiddenRowsManager().onCommit();s.getOptHiddenRowColManager().reset();s.getOptHiddenRowColManager().onCommit();}
fn make(h:&Value)->KmoRowInfo{let a=h["args"].as_array().unwrap();let n=|i:usize|a[i].as_i64().unwrap()as i32;if h["ancestor"]==true{KmoRowInfo::newAncestorAtom(n(0),n(1)as i16,n(2)as i16,7,true,true,true,true,true,true)}else if a.len()==1{KmoRowInfo::new(n(0))}else{KmoRowInfo::KmoRowInfo(n(0),n(1)as i16,n(2)as i16,n(3)as i16)}}
fn history(h:&Value,book:&KmoBook)->Value{book.transaction().discard();book.transaction().reset();book.transaction().setEnable(true);let sheet=book.getActiveSheet();clear(&sheet.borrow());let r=make(h);let mut copy=None;let mut held:Option<Rc<KmoRowRange>>=None;let mut iter=None;let mut rows=vec![];for a in h["ops"].as_array().unwrap(){let c=call(||{let n=|i:usize|a[i].as_i64().unwrap()as i32;let b=|i:usize|a[i].as_bool().unwrap();match a[0].as_str().unwrap(){"attach"=>r.setHiddenRowsManager(if a[1].as_bool().unwrap_or(true){Some(sheet.clone())}else{None}),"hidden"=>r.setHidden(b(1)),"filter"=>r.setHiddenForFilter(b(1)),"hiddenAttr"=>r.setHiddenAttr(b(1)),"resetAttr"=>r.resetHiddenAttr(if a[2].as_bool().unwrap_or(true){Some(&sheet)}else{None},b(1)),"row"=>r.setRowIndex(n(1)),"height"=>r.setHeight(n(1)as i16),"xf"=>r.setXFIndex(n(1)as i16),"rawXF"=>r.setRawXFIndex(n(1)as i16),"flags"=>r.setOptionFlags(n(1)as i16),"getFlags"=>return json!(r.getOptionFlags()),"unsynced"=>r.setUnsynced(b(1)),"formatted"=>r.setIsFormatted(b(1)),"max"=>r.setMaxHeightCell(n(1)),"min"=>r.setMinHeightCell(n(1)),"copy"=>copy=Some(r.copy()),"copyHeight"=>copy.as_ref().expect("NullPointerException").setHeight(n(1)as i16),"start"=>book.transaction().start(),"commit"=>book.transaction().commit(),"discard"=>book.transaction().discard(),"undo"=>book.undo(),"redo"=>book.redo(),"enable"=>book.transaction().setEnable(b(1)),"managerHidden"=>sheet.borrow().getHiddenRowsManager().setHidden(n(1),b(2)),"operableRow"=>sheet.borrow().getOptHiddenRowColManager().setRowOperable(n(1),b(2)),"operableCol"=>sheet.borrow().getOptHiddenRowColManager().setColOperable(n(1),b(2)),"hold"=>{held=Some(sheet.borrow().getHiddenRowsManager().getRowRange());iter=Some(held.as_ref().unwrap().iterator());},"heldAdd"=>held.as_ref().expect("NullPointerException").addRow(n(1)),"next"=>{let p=iter.as_mut().expect("NullPointerException").next();return json!([p.first,p.second]);},"hasNext"=>return json!(iter.as_ref().expect("NullPointerException").hasNext()),"resetOpt"=>sheet.borrow().getOptHiddenRowColManager().reset(),"init"=>sheet.borrow().getOptHiddenRowColManager().setInit(b(1)),"copyManagers"=>{let hidden=sheet.borrow().getHiddenRowsManager();hidden.copy(Some(&hidden));let opt=sheet.borrow().getOptHiddenRowColManager();opt.copy(Some(&opt));},s=>panic!("unknown {s}")}Value::Null});let hidden=sheet.borrow().getHiddenRowsManager();let opt=sheet.borrow().getOptHiddenRowColManager();let(wr,wc)=opt.reviewWriteFlags();let mut o=json!({"call":c,"row":row(&r),"started":book.transaction().isTransStarted(),"undo":book.canUndo(),"redo":book.canRedo(),"hidden":pairs(hidden.iterator()),"operableRows":pairs(opt.rowIterator()),"operableCols":pairs(opt.colIterator()),"rangeSize":[opt.getRowRangeSize(),opt.getColRangeSize()],"writeFlags":[hidden.reviewHasWrite(),wr,wc],"init":opt.isInit()});if let Some(c)=&copy{o["copy"]=row(c);o["equalCopy"]=json!(r.equals(Some(c)));}if let Some(h)=&held{o["held"]=json!(h.toString());o["sameRange"]=json!(Rc::ptr_eq(&hidden.getRowRange(),h));}rows.push(o);}book.transaction().discard();book.transaction().reset();clear(&sheet.borrow());json!({"rows":rows})}
fn compare(a:&Value,b:&Value,path:&str){match(a,b){(Value::Object(x),Value::Object(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(k,v)in x{compare(v,y.get(k).unwrap(),&format!("{path}.{k}"));}},(Value::Array(x),Value::Array(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(i,(a,b))in x.iter().zip(y).enumerate(){compare(a,b,&format!("{path}[{i}]"));}},_=>assert_eq!(a,b,"{path}")}}
#[test]fn original_android_row_atom_hidden_manager_transaction_histories(){let root=std::path::Path::new(env!("CARGO_MANIFEST_DIR"));let p=root.join("rewrite-review/milestones/m4-edit-save/evidence/row-atom-r0b69");let input:Value=serde_json::from_slice(&std::fs::read(p.join("inputs.json")).unwrap()).unwrap();let java:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();let api=KmoBookApi::KmoBookApi();assert_eq!(api.open(root.join("rewrite-review/milestones/m1-xlsx-grid-read/fixtures/basic-types.xlsx").to_str().unwrap(),None,true),1);std::thread::sleep(std::time::Duration::from_millis(1000));let book=api.book();let actual=json!({"histories":input["histories"].as_array().unwrap().iter().map(|h|history(h,&book)).collect::<Vec<_>>()});std::fs::write(p.join("rust.json"),serde_json::to_vec_pretty(&actual).unwrap()).unwrap();compare(&actual,&java,"root");}
